  'Playback, comments, likes, watch later, subscriptions, notifications, messages, playlists, and language settings are available through the main navigation and account menu.' => 'پلی بیک، تبصرې، خوښونه، وروسته وګورئ، ګډون، خبرتیاوې، پیغامونه، پلی لیستونه، او د ژبې ترتیبات د اصلي نیویګیشن او حساب مینو له لارې شتون لري.',
