  'PlayHub is the video platform running on this deployment, built for creators, viewers, communities, and platform operators.' => 'PlayHub د ویډیو پلیټ فارم دی چې پدې ګمارلو کې پرمخ ځي، د جوړونکو، لیدونکو، ټولنو، او پلیټ فارم چلونکو لپاره جوړ شوی.',
  'PlayHub provides creator channels, video uploads, scheduled publishing, subscriptions, comments, playlists, watch later, live content pages, and administration tools from one platform.' => 'PlayHub د یو پلیټ فارم څخه جوړونکي چینلونه ، ویډیو اپلوډونه ، مهالویش خپرول ، ګډونونه ، تبصرې ، پلی لیستونه ، وروسته وګورئ ، د مینځپانګې ژوندۍ پا pagesې ، او اداري وسیلې چمتو کوي.',
  'PlayHub uses essential cookies and browser storage for login sessions, API authentication, CSRF/security behavior, language selection, theme selection, account menu state, and other features required for the application to work.' => 'PlayHub د ننوتلو غونډو لپاره اړین کوکیز او د براوزر ذخیره کاروي، د API تصدیق، CSRF/امنیت چلند، د ژبې انتخاب، د موضوع انتخاب، د حساب مینو حالت، او د غوښتنلیک د کار کولو لپاره اړین نور ځانګړتیاوې.',
