  'Select one or more video files, enter required details, choose category and language, add a thumbnail, choose visibility, and publish. Large files are uploaded in chunks before the server starts processing.' => 'یو یا څو ویډیو فایلونه غوره کړئ، اړین توضیحات دننه کړئ، کټګورۍ او ژبه غوره کړئ، تمبنیل اضافه کړئ، لید غوره کړئ، او خپور کړئ. لوی فایلونه مخکې له دې چې سرور پروسس پیل کړي په ټوټو کې اپلوډ کیږي.',
