  'Terms of Use' => 'د کارولو شرایط',
  'The configured' => 'ترتیب شوی',
  'The developer page is connected to the Laravel backend: route inventory, platform counts, upload limits, and metadata are loaded from /api/developers.' => 'د پراختیا کونکي پاڼه د ژوندی لارویل بیکینډ سره تړلې ده: د لارې لیست، د ډیټابیس شمیرې، د اپلوډ محدودیتونه، او د پلیټ فارم میټاډاټا د /api/developers څخه ډک شوي.',
  'The frontend stores preferences such as selected language, theme, playback queue, watch progress, and interface state so the experience remains consistent across page navigation and reloads.' => 'فرنټ اینډ غوره توبونه ذخیره کوي لکه غوره شوې ژبه، موضوع، د پلې بیک کتار، لید پرمختګ، او د انٹرفیس حالت نو تجربه د پاڼې نیویګیشن او بیالوډونو کې دوامداره پاتې کیږي.',
  'The processing job encodes renditions, creates thumbnails when needed, stores captions, and marks videos ready when processing completes. Future scheduled videos remain private until the scheduler releases them.' => 'د پروسس کولو دنده رینډیشنونه کوډ کوي، د اړتیا په وخت کې تمبیلونه جوړوي، سرلیکونه ذخیره کوي، او ویډیوګانې چمتو کوي کله چې پروسس بشپړ شي. راتلونکي مهالویش شوي ویډیوګانې تر هغه پورې شخصي پاتې کیږي تر څو چې مهالویش یې خوشې نه کړي.',
  'The upload system supports categories and languages from the API, processes uploaded videos, stores thumbnails and captions, and keeps scheduled content private until its release time.' => 'د اپلوډ سیسټم د ډیټابیس لخوا ملاتړ شوی، د API څخه د کټګوریو او ژبو ملاتړ کوي، اپلوډ شوي ویډیوګانې پروسس کوي، تمبیلونه او کیپشنونه ذخیره کوي، او د خپریدو وخت پورې ټاکل شوي مینځپانګې شخصي ساتي.',
  'This page explains how PlayHub uses cookies and browser storage for sessions, security, preferences, playback, and authenticated features.' => 'دا پاڼه تشریح کوي چې څنګه PlayHub د غونډو، امنیت، غوره توبونو، پلے بیک، او مستند شوي ځانګړتیاوو لپاره کوکیز او د براوزر ذخیره کاروي.',
