  'Upload, watch, subscribe, moderate, and build with live PlayHub data.' => 'اپلوډ کړئ، وګورئ، ګډون وکړئ، اعتدال وکړئ، او د ژوندی PlayHub ډیټا سره جوړ کړئ.',
  'Uploaded videos' => 'پورته شوي ویډیوګانې',
  'Uploaded videos are encoded into playable renditions. Processing time depends on file size, duration, server load, and queue status. The upload page and Creator Studio show the current processing status.' => 'اپلوډ شوي ویډیوګانې د چلولو وړ رینډیشنونو کې کوډ شوي دي. د پروسس کولو وخت د فایل اندازه، موده، د سرور بار، او د قطار حالت پورې اړه لري. د اپلوډ پاڼه او د خالق سټوډیو د ویډیو ریکارډ څخه د اصلي پروسس کولو حالت ښیې.',
  'Uploads, scheduling, and processing are available.' => 'اپلوډونه، مهال ویش، او پروسس کول شتون لري.',
  'Use /api/videos, channel endpoints, and authenticated routes for creator workflows.' => 'د جوړونکي کاري فلو لپاره /api/ویډیوګانې، د چینل پای ټکي، او مستند شوي لارې وکاروئ.',
  'Use built-in report actions for videos and comments so admins receive the exact content reference. Admin dashboard pages show users, content, reports, monetization, analytics, support, roles, and system settings.' => 'د ویډیوګانو او نظرونو لپاره د راپور جوړ شوي عملونه وکاروئ ترڅو مدیران د مینځپانګې دقیق حواله ترلاسه کړي. د اډمین ډشبورډ پاڼې د کاروونکو، منځپانګې، راپورونو، پیسو مینځلو، تحلیلونو، ملاتړ، رولونو، او سیسټم ترتیباتو لپاره د ژوندی ډیټابیس ډاټا کاروي.',
  'Use Contact Us' => 'زموږ سره اړیکه وکاروئ',
  'Use JSON for normal API requests and FormData for file uploads. Do not bypass validation: categories and languages use configured IDs, visibility is limited to public, unlisted, or private, and captions accept SRT, VTT, or TXT files.' => 'د عام API غوښتنو او د فایل اپلوډونو لپاره فارم ډیټا لپاره JSON وکاروئ. د اعتبار څخه ډډه مه کوئ: کټګورۍ او ژبې د ډیټابیس IDs دي، لیدلوری په عامه، غیر لیست شوي، یا شخصي پورې محدود دی، او سرلیکونه د SRT، VTT، یا TXT فایلونه مني.',
  'Use Settings to update your profile, security, password, two-factor delivery, devices, preferences, and notification options. If you cannot access your account, use the login flow and provide the account email to the site administrator.' => 'د خپل پروفایل، امنیت، پټنوم، دوه فکتور تحویلي، وسایل، غوره توبونه، او د خبرتیا اختیارونو تازه کولو لپاره ترتیبات وکاروئ. که تاسو خپل حساب ته لاسرسی نشئ کولی، د ننوتلو جریان وکاروئ او د سایټ مدیر ته د حساب بریښنالیک چمتو کړئ.',
  'Use the contact form' => 'د اړیکو فورمه وکاروئ',
  'Use the report actions on videos, comments, and community posts so admins receive the exact content reference.' => 'په ویډیوګانو، تبصرو، او د ټولنې پوسټونو کې د راپور کړنو څخه کار واخلئ ترڅو مدیران د منځپانګې دقیق حواله ترلاسه کړي.',
  'Use the report actions on videos, comments, and community posts when content may violate platform rules. These reports include the content reference so administrators can review the exact item.' => 'په ویډیوګانو، تبصرو، او د ټولنې پوسټونو کې د راپور عمل وکاروئ کله چې مینځپانګه ممکن د پلیټ فارم قواعد سرغړونه وکړي. دا راپورونه د اصلي مینځپانګې ریکارډ سره تړلي دي او د عمومي پیغام څخه غوره دي ځکه چې مدیران کولی شي دقیق توکي بیاکتنه وکړي.',
  'Use the right PlayHub channel for account help, content reports, technical issues, and administrator requests.' => 'د حساب مرستې ، مینځپانګې راپورونو ، تخنیکي مسلو او د مدیر غوښتنو لپاره سم PlayHub چینل وکاروئ.',
